begin;
do $tests$
declare k text:=repeat('gateway_test_only_',3);u uuid;bid uuid;mid uuid;sc jsonb;g1 jsonb;g2 jsonb;c jsonb;rk uuid:=gen_random_uuid();denied boolean;v jsonb;
begin
 select owner_id into u from regente10_portao.configuration;
 update regente10_portao.configuration set key_hash=encode(extensions.digest(k,'sha256'),'hex');
 perform set_config('request.jwt.claims','{}',true);
 denied:=false;begin perform public.regente10_gateway('worker_state','{"project":"optotica"}','invalid');exception when others then denied:=true;end;if not denied then raise exception 'Invalid key accepted';end if;
 denied:=false;begin perform public.regente10_gateway('status','{"project":"optotica"}',k);exception when others then denied:=true;end;if not denied then raise exception 'Anonymous status accepted';end if;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',u,'role','authenticated')::text,true);
 v:=public.regente10_gateway('status','{"project":"optotica"}',k);if v->>'policy'<>'s00-operative-v1' then raise exception 'Policy mismatch';end if;
 if regente10_portao.assert_resource('born-robot','OPT/CODIGO-PUBLICO','repo.metadata.read')->0->>'alias'<>'OPT/CODIGO-PUBLICO' then raise exception 'Eligible shared resource denied';end if;
 denied:=false;begin perform regente10_portao.assert_resource('ensavim','OPT/CODIGO-PUBLICO','repo.metadata.read');exception when others then denied:=true;end;if not denied then raise exception 'Cross-project resource accepted';end if;
 denied:=false;begin perform regente10_portao.assert_resource('optotica','G-PES','status.read');exception when others then denied:=true;end;if not denied then raise exception 'Personal resource accepted';end if;
 select id into bid from regente10_portao.bindings where project_id='optotica' limit 1;
 select mission_id into mid from regente10_portao.projects where project_id='optotica';
 update regente10_portao.bindings set toolkit='test_fixture_only',status='no_auth',no_auth=true,revision=1,verified_at=now() where id=bid;
 insert into regente10_portao.tools(project_id,binding_id,slug,version,contract_hash,schema,name) values('optotica',bid,'TEST_FIXTURE_ONLY','test_v1',repeat('a',64),'{"type":"object"}','Rollback fixture');
 perform public.regente10_gateway('cap','{"project":"optotica","capBrl":5,"fx":5,"confirm":true}',k);
 sc:=public.regente10_gateway('scope',jsonb_build_object('project','optotica','bindingId',bid,'toolSlug','TEST_FIXTURE_ONLY','version','test_v1','argsHash',repeat('b',64),'dataClass','internal','description','Synthetic rollback fixture, no provider calls','confirmNonPersonal',true),k);
 v:=jsonb_build_object('project','optotica','missionId',mid,'bindingId',bid,'resourceAlias',sc->>'resourceAlias','operation','instrument.execute','toolSlug','TEST_FIXTURE_ONLY','version','test_v1','contractHash',repeat('a',64),'arguments','{}'::jsonb,'argsHash',repeat('b',64),'resourceHash',repeat('c',64),'unitMaxBrl',3,'maxCalls',1,'ttlMinutes',15,'priceSource','Synthetic fixture tariff','confirm',true,'costVerified',true);
 denied:=false;begin perform public.regente10_gateway('grant',v||'{"costVerified":false}',k);exception when others then denied:=true;end;if not denied then raise exception 'Unknown cost accepted';end if;
 g1:=public.regente10_gateway('grant',v,k);g2:=public.regente10_gateway('grant',v,k);
 v:=jsonb_build_object('project','optotica','grantId',g1->>'grantId','requestKey',rk,'argsHash',repeat('b',64),'contractHash',repeat('a',64),'resourceHash',repeat('c',64));
 c:=public.regente10_gateway('claim',v,k);if c->>'reused'<>'false' then raise exception 'First claim not reserved';end if;
 if (public.regente10_gateway('claim',v,k)->>'reused')<>'true' then raise exception 'Duplicate claim not reused';end if;
 if (select reserved_brl from public.regente10_mission_budgets where mission_id=mid)<>3 then raise exception 'Duplicate reservation';end if;
 denied:=false;begin perform public.regente10_gateway('claim',v||jsonb_build_object('grantId',g2->>'grantId','requestKey',gen_random_uuid()),k);exception when others then denied:=true;end;if not denied then raise exception 'Over cap reservation accepted';end if;
 denied:=false;begin perform public.regente10_gateway('claim',v||'{"project":"ensavim"}',k);exception when others then denied:=true;end;if not denied then raise exception 'Cross project grant accepted';end if;
 update regente10_portao.bindings set revision=revision+1 where id=bid;
 denied:=false;begin perform public.regente10_gateway('arm',jsonb_build_object('project','optotica','eventId',c->'event'->>'id'),k);exception when others then denied:=true;end;if not denied then raise exception 'Reconnected binding dispatched stale grant';end if;
 update regente10_portao.bindings set revision=revision-1 where id=bid;
 update public.regente10_resources set policy_version=policy_version+1 where alias=sc->>'resourceAlias';
 denied:=false;begin perform public.regente10_gateway('arm',jsonb_build_object('project','optotica','eventId',c->'event'->>'id'),k);exception when others then denied:=true;end;if not denied then raise exception 'Changed resource policy dispatched';end if;
 update public.regente10_resources set policy_version=policy_version-1 where alias=sc->>'resourceAlias';
 perform public.regente10_gateway('arm',jsonb_build_object('project','optotica','eventId',c->'event'->>'id'),k);
 denied:=false;begin perform public.regente10_gateway('arm',jsonb_build_object('project','optotica','eventId',c->'event'->>'id'),k);exception when others then denied:=true;end;if not denied then raise exception 'Double dispatch accepted';end if;
 perform public.regente10_gateway('complete',jsonb_build_object('project','optotica','eventId',c->'event'->>'id','state','uncertain','diagnostic','test_timeout'),k);
 if (select reserved_brl from public.regente10_mission_budgets where mission_id=mid)<>3 then raise exception 'Uncertain reserve released';end if;
 denied:=false;begin perform public.regente10_gateway('cancel',jsonb_build_object('project','optotica','eventId',c->'event'->>'id'),k);exception when others then denied:=true;end;if not denied then raise exception 'Dispatched reserve cancelled';end if;
 update public.regente10_controls set emergency_stop=true where owner_id=u;
 denied:=false;begin perform public.regente10_gateway('control',jsonb_build_object('project','optotica','operation','discover','requestKey',gen_random_uuid()),k);exception when others then denied:=true;end;if not denied then raise exception 'Emergency stop bypassed';end if;
end $tests$;
rollback;
select 'PASS: key, Master, resource scope, known cost, idempotency, cap, one dispatch, uncertain reserve, emergency stop; fixtures rolled back' as validation;
